        "content": "Ключевая идея проекта — сделать сам продукт источником визуальной среды, а не просто объектом внутри кадра. Форма, материалы и конструктивная логика очков становятся основой композиции, света и motion-подачи, благодаря чему вокруг продукта собирается цельный visual world, а не отдельный packshot.",
